import path from "node:path";
import { HttpMethod } from "@rexeus/typeweaver-core";
import type {
  GeneratorContext,
  NormalizedOperation,
  NormalizedResource,
} from "@rexeus/typeweaver-gen";
import { pascalCase } from "polycase";

type OperationModel = {
  readonly className: string;
  readonly handlerName: string;
};

const generatedHeader = `/**
 * This file was automatically generated by TypeWeaver.
 * DO NOT EDIT. Modify the source contract and generate again.
 *
 * @generated by @rexeus/typeweaver-effect
 */
`;

const operationModel = (operation: NormalizedOperation): OperationModel => {
  const className = pascalCase(operation.operationId);
  return {
    className,
    handlerName: `handle${className}Request`,
  };
};

const importLines = (operations: readonly OperationModel[]): string =>
  operations
    .flatMap(operation => [
      `import type { I${operation.className}Request } from "./${operation.className}Request.js";`,
      `import type { ${operation.className}Response } from "./${operation.className}Response.js";`,
    ])
    .join("\n");

const handlerLines = (operations: readonly OperationModel[]): string =>
  operations
    .map(
      operation =>
        `  readonly ${operation.handlerName}: EffectRequestHandler<I${operation.className}Request, ${operation.className}Response, TError, TRequirements, ServerContext<TState>>;`
    )
    .join("\n");

const mapperLines = (operations: readonly OperationModel[]): string =>
  operations
    .map(
      operation =>
        `  readonly ${operation.handlerName}: EffectHandlerErrorMapper<TError, ${operation.className}Response, ServerContext<TState>>;`
    )
    .join("\n");

const adapterLines = (operations: readonly OperationModel[]): string =>
  operations
    .map(
      operation =>
        `  ${operation.handlerName}: (request, context) =>
    runtime.run(
      handlers.${operation.handlerName},
      request,
      context,
      errorMappers.${operation.handlerName}
    ),`
    )
    .join("\n");

const resourceSource = (resource: NormalizedResource): string => {
  const resourceName = pascalCase(resource.name);
  const operations = resource.operations
    .filter(operation => operation.method !== HttpMethod.HEAD)
    .map(operationModel);

  return `${generatedHeader}
import type {
  EffectHandlerErrorMapper,
  EffectHandlerRuntime,
  EffectRequestHandler,
} from "@rexeus/typeweaver-effect";
import type { ServerContext } from "../lib/server/index.js";
import type { Server${resourceName}ApiHandler } from "./${resourceName}Router.js";
${importLines(operations)}

export type Effect${resourceName}ApiHandler<
  TError,
  TRequirements,
  TState extends Record<string, unknown> = Record<string, unknown>,
> = {
${handlerLines(operations)}
};

export type Effect${resourceName}ErrorMappers<
  TError,
  TState extends Record<string, unknown> = Record<string, unknown>,
> = {
${mapperLines(operations)}
};

export const adapt${resourceName}EffectHandlers = <
  TError,
  TRequirements,
  TState extends Record<string, unknown> = Record<string, unknown>,
>(
  runtime: EffectHandlerRuntime<TRequirements>,
  handlers: Effect${resourceName}ApiHandler<TError, TRequirements, TState>,
  errorMappers: Effect${resourceName}ErrorMappers<TError, TState>
): Server${resourceName}ApiHandler<TState> => ({
${adapterLines(operations)}
});
`;
};

export const generateEffectHandlers = (context: GeneratorContext): void => {
  for (const resource of context.normalizedSpec.resources) {
    const outputDir = context.getResourceOutputDir(resource.name);
    const resourceName = pascalCase(resource.name);
    context.writeFile(
      path.relative(
        context.outputDir,
        path.join(outputDir, `Effect${resourceName}ApiHandler.ts`)
      ),
      resourceSource(resource)
    );
  }
};
